query hentPersonopplysninger($behandlingID: Long!) {
  hentSaksopplysninger(behandlingID: $behandlingID) {
    persondata {
      navn {
        fornavn
        mellomnavn
        etternavn
        __typename
      }
      kjoenn
      folkeregisterpersonstatuser {
        kode
        erHistorisk
        __typename
      }
      folkeregisteridentifikator
      statsborgerskap {
        land
        erHistorisk
        __typename
      }
      sivilstand {
        type
        erHistorisk
        __typename
      }
      __typename
    }
    __typename
  }
}

query hentNavn($ident: String!) {
  hentPersonopplysninger(ident: $ident) {
    navn {
      fornavn
      mellomnavn
      etternavn
      __typename
    }
    __typename
  }
}
